DECLARE
    V_REQUEST_ID RAW(16);
    V_JSON       CLOB;
BEGIN

    V_REQUEST_ID :=
        HEXTORAW(
            REPLACE(
                '{{ JS_PAGE.getRequestId() }}',
                '-',
                ''
            )
        );

    V_JSON :=
        '{{ JSON.stringify(JS_PAGE.getRequestData()) }}';

    TALY_BO_REP.MMS_ONBOARDING_PKG.UPDATE_REQUEST(
        P_REQUEST_ID   => V_REQUEST_ID,
        P_REQUEST_JSON => V_JSON,
        P_ACTION       => 'SUBMIT'
    );

END;
